/* Hairline figure adapted for direct manipulation in Feynman's apply workshop.
 * The kernel and bench remain unchanged. Parent controls own task state.
 */
const { Cam, fit, proj, facing, rings, prism, solid, put, mk, poly, open, circ, ringAt,
  spring, stepS, tween, tset, tval, tdone, pointer, register, disposer, clamp } = HL;
function mount({ stage, svg, read }) {
  simulationInteractions(svg);
  const bag = disposer(), C = Cam(45, .5, 1.65);
  fit(C, [[-90,-25,0],[90,25,0],[-90,0,100],[90,0,100]], 200, 166);
  const P = proj(C), front = facing(C), root = mk('g', {}, svg);
  const base = solid(root), post = solid(root), beam = solid(root);
  const ticks = mk('path', {class:'nf lo'}, root);
  const weights = [solid(root), solid(root)], handles = [mk('path', {class:'nf lo'}, weights[0].g), mk('path', {class:'sim-grab'}, weights[1].g)];
  const jewelBase = solid(root), jewel = solid(root);
  const pulse = mk('path', {class:'nf hi'}, root);
  let config = { left: -3, right: 1, leftMass: 4, rightMass: 6, checked: false, solved: false };
  const tilt = spring(0), xs = [spring(-42), spring(14)], win = tween(0);
  let last = '', drag = null;

  function block(item, x0,y0,x1,y1,r,z0,z1, project = P) {
    const [outer,inner] = rings(x0,y0,x1,y1,r,Math.min(1,(x1-x0)/6,(y1-y0)/6));
    put(item, prism(project,front,outer,inner,z0,z1));
  }
  function draw(a, left, right, completion) {
    block(base,-27,-22,27,22,7,0,6);
    block(post,-6,-6,6,6,3,6,58);
    const B = (x,y,z) => P(x*Math.cos(a)-(z-60)*Math.sin(a),y,60+x*Math.sin(a)+(z-60)*Math.cos(a));
    block(beam,-90,-9,90,9,4,58,63,B);
    ticks.setAttribute('d',Array.from({length:13},(_,i)=>{const x=(i-6)*14;return open([B(x,-6,63),B(x,-2,63)])}).join(''));
    [left,right].forEach((x,i)=>{
      const h = 9 + (i ? config.rightMass : config.leftMass)*5;
      block(weights[i],x-9,-8,x+9,8,3,63,63+h,B);
      handles[i].setAttribute('d',poly([B(x-7,-6,63+h),B(x+7,-6,63+h),B(x+7,6,63+h),B(x-7,6,63+h)]));
    });
    block(jewelBase,45,30,73,53,5,0,5);
    block(jewel,51,36,67,47,3,5,10+completion*28);
    jewel.sil.classList.toggle('hi',config.solved);
    weights[1].sil.classList.add('sim-grab-edge'); weights[1].g.setAttribute('class', 'sim-grabbable');
    pulse.setAttribute('d',completion>0 && completion<1 ? open(ringAt(P,circ(10+completion*32,60).map(q=>({...q,u:q.u+59,v:q.v+41})),3)) : '');
  }
  const loop = register(stage,(dt,now)=>{
    const moving = [tilt,...xs].map(s=>stepS(s,dt)).some(Boolean);
    const completion = tval(win,now), key = [tilt.x,xs[0].x,xs[1].x,completion,config.leftMass,config.rightMass,drag?.i,config.solved].join(',');
    if(key!==last){draw(tilt.x,xs[0].x,xs[1].x,completion);last=key;}
    return moving || !tdone(win,now);
  });
  function update(next) {
    config=next;stage.setAttribute('data-solved',String(config.solved));
    xs[0].t=config.left*14; xs[1].t=config.right*14;
    tilt.t=config.checked?clamp((config.leftMass*Math.abs(config.left)-config.rightMass*config.right)*.023,-.26,.26):0;
    tset(win,config.solved?1:0,performance.now(),0);
    read.textContent=config.solved?'balanced':'move a weight';loop.wake();
  }
  bag.add(pointer(stage,{
    down:(p,e)=>{
      if(config.solved)return;
      // Pick the whole weight in its TARGET pose, including the beam's tilt.
      // A level-beam centre misses the body once the right side drops far enough.
      const a=tilt.t;
      const x=config.right*14,h=9+config.rightMass*5,corners=[];
      for(const u of [x-9,x+9])for(const v of [-8,8])for(const z of [63,63+h])
        corners.push(P(u*Math.cos(a)-(z-60)*Math.sin(a),v,60+u*Math.sin(a)+(z-60)*Math.cos(a)));
      const bounds=[Math.min(...corners.map(q=>q[0]))-6,Math.max(...corners.map(q=>q[0]))+6,Math.min(...corners.map(q=>q[1]))-6,Math.max(...corners.map(q=>q[1]))+6];
      if(p[0]<bounds[0]||p[0]>bounds[1]||p[1]<bounds[2]||p[1]>bounds[3])return;
      drag={i:1,start:p[0],x:config.right};
      stage.setPointerCapture(e.pointerId);stage.setAttribute('data-dragging','true');loop.wake();
    },
    move:p=>{
      if(!drag)return;
      const delta=(p[0]-drag.start)/(P(14,0,60)[0]-P(0,0,60)[0]);
      const value=clamp(drag.x+delta,drag.i?1:-6,drag.i?6:-1);
      window.parent.postMessage({type:'feynman-balance-move',side:drag.i?'right':'left',value},window.location.origin);
    },
    leave:()=>{if(!drag)read.textContent=config.solved?'balanced':'move a weight';},
  }));
  const release=()=>{drag=null;stage.removeAttribute('data-dragging');loop.wake();};
  bag.on(stage,'lostpointercapture',release);
  bag.on(window,'message',e=>{if(e.source===window.parent&&e.origin===window.location.origin&&e.data?.type==='feynman-balance-state')update(e.data.config);});
  bag.add(loop.unregister);bag.add(()=>svg.replaceChildren());
  update(config);
  return {set:()=>{},destroy:bag.dispose};
}
hairline({name:'balance',means:'Move the weights until both turning effects match.',rules:[1,3,4,5,6,7,8,9,10],range:[1,2,3],tour:[[150,130],[245,130],null],mount});

const {Cam,fit,proj,unproj,facing,rings,circ,run,ringAt,prism,solid,put,mk,open,poly,spring,stepS,pointer,register,disposer}=HL;
function mount({stage,svg,read}) {
 const treatment=simulationInteractions(svg),bag=disposer(),C=Cam(45,.5,1.38);
 fit(C,[[-90,-70,0],[95,110,65]],200,148);
 const P=proj(C),front=facing(C),root=mk('g',{},svg);
 const wire=mk('path',{class:'nf lo'},root),flow=mk('path',{class:'nf hi'},root);
 const objects=[],part=(x,y)=>{const g=mk('g',{},root);const p={g,x,y};objects.push(p);return p;};
 function block(s,x0,y0,x1,y1,r,z0,z1){const[a,b]=rings(x0,y0,x1,y1,r,1);put(s,prism(P,front,a,b,z0,z1));}
 const battery=part(-65,-10);block(solid(battery.g),-77,-29,-53,9,4,0,25);block(solid(battery.g),-71,-18,-59,-2,2,25,29);
 const socket=part(-30,-55);block(solid(socket.g),-55,-67,-5,-43,4,0,3);
 treatment.top(socket.g,[P(-53,-65,3),P(-7,-65,3),P(-7,-45,3),P(-53,-45,3)],'drop');
 const lamp=part(65,8);block(solid(lamp.g),53,-8,77,24,5,0,8);
 // The screw holder rises directly from the base. Anchor the glass neck inside
 // its rim, then paint that rim in front of the glass to seat the bulb in it.
 const holderRing=circ(7.5,48).map(q=>({...q,u:q.u+65,v:q.v+8}));
 const holderInner=circ(6.5,48).map(q=>({...q,u:q.u+65,v:q.v+8}));
 put(solid(lamp.g),prism(P,front,holderRing,holderInner,8,14));
 for(const z of [9.5,11.5,13.5])mk('path',{class:'nf lo',d:open(ringAt(P,run(holderRing,front),z))},lamp.g);
 const [bx,neckY]=P(65,8,16),by=neckY-31;
 const bulb=mk('path',{class:'sil','data-lamp-part':'glass'},lamp.g),filament=mk('path',{class:'nf'},lamp.g);
 bulb.setAttribute('d',`M ${bx-5} ${neckY} L ${bx+5} ${neckY} L ${bx+5} ${neckY-7} C ${bx+8} ${neckY-14} ${bx+23} ${neckY-17} ${bx+23} ${neckY-31} C ${bx+23} ${neckY-44} ${bx+13} ${neckY-54} ${bx} ${neckY-54} C ${bx-13} ${neckY-54} ${bx-23} ${neckY-44} ${bx-23} ${neckY-31} C ${bx-23} ${neckY-17} ${bx-8} ${neckY-14} ${bx-5} ${neckY-7} Z`);
 mk('path',{class:'nf lo',d:`M ${bx-14} ${by-4} C ${bx-15} ${by-11} ${bx-9} ${by-17} ${bx-3} ${by-18}`},lamp.g);
 filament.setAttribute('d',open([[bx-3,neckY-5],[bx-6,by+4],[bx-3,by],[bx,by+4],[bx+3,by],[bx+6,by+4],[bx+3,neckY-5]]));
 const rim=solid(lamp.g);rim.g.setAttribute('data-lamp-part','socket-rim');
 put(rim,prism(P,front,holderRing,holderInner,14,18));
 const rays=mk('path',{class:'nf hi'},lamp.g);
 wire.setAttribute('d',open([P(-65,-29,2),P(-65,-55,2),P(-55,-55,2)])+open([P(-5,-55,2),P(65,-55,2),P(65,-8,2)])+open([P(65,24,2),P(65,47,2),P(-65,47,2),P(-65,9,2)]));
 const homes=[[-58,88],[0,88],[58,88]];
 const items=homes.map(([x,y])=>{const item=part(x,y);item.body=solid(item.g);item.top=mk('path',{class:'sim-grab'},item.g);item.label=treatment.label(item.g,'',P(x,y+18,0));item.pos=[spring(x),spring(y),spring(5)];item.g.setAttribute('class','sim-grabbable');return item;});
 let config={selected:null,options:[15,30,60],voltage:6,checked:false,solved:false},drag=null,last='';
 const light=spring(0),win=spring(0);
 function targets(){items.forEach((item,i)=>{if(drag?.i===i)return;const installed=config.selected===i;item.pos[0].t=installed?-30:homes[i][0];item.pos[1].t=installed?-55:homes[i][1];item.pos[2].t=installed?3:5;});}
 function update(next){config=next;stage.setAttribute('data-solved',String(config.solved));targets();const on=config.checked&&config.selected!==null&&Math.abs(config.voltage/config.options[config.selected]-.2)<.0001;light.t=on?1:0;win.t=config.solved?1:0;read.textContent=on?'lamp on':'choose resistor';last='';loop.wake();}
 const loop=register(stage,dt=>{
  const moving=[light,win,...items.flatMap(i=>i.pos)].map(s=>stepS(s,dt)).some(Boolean);
  const key=[light.x,win.x,...items.flatMap(i=>i.pos.map(s=>s.x)),drag?.i].join(',');if(key===last)return moving;last=key;
  items.forEach((item,i)=>{const[x,y,height]=item.pos.map(s=>s.x),z=Math.max(3,height);item.x=x;item.y=y;
   block(item.body,x-20,y-8,x+20,y+8,3,z,z+10);item.body.sil.classList.add('sim-grab-edge');
   item.top.setAttribute('d',poly([P(x-17,y-6,z+10),P(x+17,y-6,z+10),P(x+17,y+6,z+10),P(x-17,y+6,z+10)]));
   item.label.textContent=`${config.options[i]} Ω`;const p=P(x,y+18,z);item.label.setAttribute('x',p[0]);item.label.setAttribute('y',p[1]+6);
  });
  // The socket is a support surface, so it must precede the elevated components
  // throughout their springs' overshoot, rather than compete at the same depth.
  root.append(socket.g);
  objects.filter(o=>o!==socket).sort((a,b)=>(a.x+a.y)-(b.x+b.y)).forEach(o=>root.append(o.g));
  filament.classList.toggle('hi',light.x>.1);
  rays.setAttribute('d',light.x>.01?Array.from({length:10},(_,i)=>{const a=i/10*Math.PI*2;return open([[bx+Math.cos(a)*27,by+Math.sin(a)*27],[bx+Math.cos(a)*(27+light.x*8+win.x*10),by+Math.sin(a)*(27+light.x*8+win.x*10)]]);}).join(''):'');
  flow.setAttribute('d',config.checked&&config.selected!==null?wire.getAttribute('d'):'');return moving;
 });
 function release(){if(!drag)return;const i=drag.i,item=items[i];const dropped=Math.hypot(item.pos[0].t+30,item.pos[1].t+55)<27;
  const selected=dropped?i:config.selected===i?null:config.selected;drag=null;stage.removeAttribute('data-dragging');config={...config,selected};targets();loop.wake();
  parent.postMessage({type:'feynman-circuit-select',value:selected},location.origin);
 }
 bag.add(pointer(stage,{down:(p,e)=>{if(config.solved)return;
  const distances=items.map(item=>{const q=P(item.pos[0].t,item.pos[1].t,item.pos[2].t+10);return Math.hypot(q[0]-p[0],q[1]-p[1]);});
  const i=distances.indexOf(Math.min(...distances));if(distances[i]>30)return;
  const [x,y]=unproj(C,p[0],p[1],22);drag={i,dx:items[i].pos[0].t-x,dy:items[i].pos[1].t-y};items[i].pos[2].t=22;
  stage.setPointerCapture(e.pointerId);stage.setAttribute('data-dragging','true');loop.wake();
 },move:p=>{if(!drag)return;const[x,y]=unproj(C,p[0],p[1],22),item=items[drag.i];item.pos[0].t=Math.max(-95,Math.min(95,x+drag.dx));item.pos[1].t=Math.max(-65,Math.min(112,y+drag.dy));loop.wake();},leave:()=>{}}));
 bag.on(stage,'lostpointercapture',release);
 bag.on(window,'message',e=>{if(e.source===parent&&e.origin===location.origin&&e.data?.type==='feynman-circuit-state')update(e.data.config);});
 bag.add(loop.unregister);bag.add(()=>svg.replaceChildren());update(config);return{set:()=>{},destroy:bag.dispose};
}
hairline({name:'circuit',means:'Choose a resistor and snap it into the circuit to supply the required lamp current.',rules:[1,3,6,7,8,9],range:[1,2,3],tour:[[140,230],[200,140],null],mount});

const {Cam,fit,proj,facing,rings,prism,solid,put,mk,open,poly,spring,stepS,pointer,register,disposer,clamp}=HL;
function mount({stage,svg,read}) {
 const treatment=simulationInteractions(svg),bag=disposer(),C=Cam(0,.55,1.8);
 fit(C,[[-60,-25,0],[100,35,90]],230,150);
 const P=proj(C),front=facing(C),root=mk('g',{},svg);
 const ground=mk('path',{class:'nf dash lo'},root),foot=solid(root),tower=solid(root),deck=solid(root),landing=mk('path',{class:'sim-drop'},root);
 const ladder=mk('g',{class:'sim-grabbable'},root),rungs=Array.from({length:8},()=>solid(ladder));
 const rails=[solid(ladder),solid(ladder)],grips=[mk('path',{class:'sim-grab'},ladder),mk('path',{class:'sim-grab'},ladder)];
 const gate=solid(root),arc=mk('path',{class:'nf lo'},root);
 const labels=[treatment.label(root,'',[0,0],true),treatment.label(root,'',[0,0],true),treatment.label(root,'',[0,0],true)];
 let config={angle:20,length:10,rise:6,run:8,checked:false,solved:false},drag=null,last='';const angle=spring(10),win=spring(0);
 function block(s,x0,y0,x1,y1,r,z0,z1,project=P){const[a,b]=rings(x0,y0,x1,y1,r,Math.min(1,(x1-x0)/5,(y1-y0)/5));put(s,prism(project,front,a,b,z0,z1));}
 function label(node,text,p){node.textContent=text;node.setAttribute('x',p[0]);node.setAttribute('y',p[1]);}
 function update(next){config=next;stage.setAttribute('data-solved',String(config.solved));angle.t=config.checked?config.angle:10;win.t=config.solved?1:0;read.textContent=config.solved?'ladder secured':'set ladder angle';last='';loop.wake();}
 const loop=register(stage,dt=>{
  const moving=[angle,win].map(s=>stepS(s,dt)).some(Boolean),key=[angle.x,win.x].join(',');if(key===last)return moving;last=key;
  const scale=8,L=config.length*scale,h=config.rise*scale,x=-50+config.run*scale,a=angle.x*Math.PI/180;
  // The tower is behind the ladder in world y. Its landing projects forward.
  block(foot,-55,0,-45,20,2,-3,0);
  block(tower,x+3,-24,x+24,-4,4,0,h+15);block(deck,x-7,-7,x+25,23,4,h-4,h);
  landing.setAttribute('d',poly([P(x-5,1,h),P(x+5,1,h),P(x+5,20,h),P(x-5,20,h)]));
  const B=(u,v,z)=>P(-50+u*Math.cos(a)-z*Math.sin(a),v,u*Math.sin(a)+z*Math.cos(a));
  rungs.forEach((r,i)=>{const u=(i+1)*L/9;block(r,u-1.5,4,u+1.5,16,1,0,3,B);});
  rails.forEach((rail,i)=>{const y=i?16:1;block(rail,0,y,L,y+3,1.4,0,5,B);rail.sil.classList.add('sim-grab-edge');grips[i].setAttribute('d',poly([B(1,y+.4,5),B(L-1,y+.4,5),B(L-1,y+2.6,5),B(1,y+2.6,5)]));});
  block(gate,x+4,1,x+8,21,1.5,h,h+3+win.x*12);
  ground.setAttribute('d',open([P(-50,10,0),P(x,10,0),P(x,10,h)]));
  arc.setAttribute('d',open(Array.from({length:20},(_,i)=>P(-50+18*Math.cos(a*i/19),10,18*Math.sin(a*i/19)))));
  label(labels[0],`${config.run} m`,P(-50+config.run*4,26,0));label(labels[1],`${config.rise} m`,P(x+30,-8,h/2));
  label(labels[2],`${config.length} m`,B(L/2,-4,8));return moving;
 });
 bag.add(pointer(stage,{down:(p,e)=>{if(config.solved)return;const a=angle.t*Math.PI/180;
  const start=P(-50,10,0),end=P(-50+config.length*8*Math.cos(a),10,config.length*8*Math.sin(a));
  const dx=end[0]-start[0],dy=end[1]-start[1],t=clamp(((p[0]-start[0])*dx+(p[1]-start[1])*dy)/(dx*dx+dy*dy),0,1);
  if(Math.hypot(p[0]-start[0]-t*dx,p[1]-start[1]-t*dy)>24)return;
  drag={y:p[1],angle:config.angle};stage.setPointerCapture(e.pointerId);stage.setAttribute('data-dragging','true');
 },move:p=>{if(drag)parent.postMessage({type:'feynman-ladder-angle',value:clamp(drag.angle+(drag.y-p[1])*.5,10,75)},location.origin);},leave:()=>{}}));
 bag.on(stage,'lostpointercapture',()=>{drag=null;stage.removeAttribute('data-dragging');});
 bag.on(window,'message',e=>{if(e.source===parent&&e.origin===location.origin&&e.data?.type==='feynman-ladder-state')update(e.data.config);});
 bag.add(loop.unregister);bag.add(()=>svg.replaceChildren());update(config);return{set:()=>{},destroy:bag.dispose};
}
hairline({name:'ladder',means:'Set the ladder angle to reach a balcony with a known height and horizontal distance.',rules:[1,3,6,7,8,9],range:[1,2,3],tour:[[180,170],[200,130],null],mount});
